function icons(root=document){root.querySelectorAll('[data-icon]:not([data-ready])').forEach(el=>{el.dataset.ready='1';if(el.classList.contains('nav')){let text=[...el.childNodes].find(n=>n.nodeType===3&&n.textContent.trim());if(text){let s=document.createElement('span');s.className='label';s.textContent=text.textContent.trim();text.remove();el.prepend(s)}}el.insertAdjacentHTML('afterbegin',`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">${ICONS[el.dataset.icon]||''}</svg>`)})}icons();

const EMPTY={profile:{name:'',xp:0,streak:0,record:0},transactions:[],tasks:[],habits:[],goals:[],investments:[],events:[],moods:[],notes:[],focusSessions:[],portfolioHistory:[]};
let state=(()=>{try{return {...structuredClone(EMPTY),...JSON.parse(localStorage.getItem('luar-state'))}}catch{return structuredClone(EMPTY)}})();
state.profile.xpClaims=state.profile.xpClaims&&typeof state.profile.xpClaims==='object'?state.profile.xpClaims:{};
state.habits.forEach(h=>{h.history=Array.isArray(h.history)?h.history:(h.completedDate?[h.completedDate]:[]);h.xpDates=Array.isArray(h.xpDates)?h.xpDates:[];h.createdAt=h.createdAt||new Date().toISOString();delete h.completedDate});
state.tasks.forEach(t=>{if(typeof t.xpAwarded!=='boolean')t.xpAwarded=!!t.completed;t.status=t.completed?'completed':t.status==='progress'?'progress':'todo'});
