const money=v=>(+v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'}),safe=v=>String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])),dateKey=(d=new Date())=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`,today=()=>dateKey(),formatDate=v=>{let m=String(v||'').match(/^(\d{4})-(\d{2})-(\d{2})/);return m?`${m[3]}/${m[2]}/${m[1]}`:(v||'Sem data')},id=()=>crypto.randomUUID?.()||Date.now().toString(36);
function awardXP(key,amount){if(state.profile.xpClaims[key])return false;state.profile.xpClaims[key]=new Date().toISOString();state.profile.xp=(+state.profile.xp||0)+amount;return true}
const empty=(i,t,s)=>`<div class="empty"><span>${i}</span><b>${t}</b><small>${s}</small></div>`,actions=(e,id,done=false)=>`<div class="row-actions">${done?`<button data-action="complete" data-entity="${e}" data-id="${id}">✓</button>`:''}<button data-action="edit" data-entity="${e}" data-id="${id}">✎</button><button class="danger" data-action="delete" data-entity="${e}" data-id="${id}">×</button></div>`;
function save(){recordPortfolioSnapshot();localStorage.setItem('luar-state',JSON.stringify(state));render()}
function recordPortfolioSnapshot(){state.portfolioHistory=Array.isArray(state.portfolioHistory)?state.portfolioHistory:[];let t=totals(),value=t.current,invested=t.invested,date=today(),found=state.portfolioHistory.find(x=>x.date===date);if(found){found.value=value;found.invested=invested}else state.portfolioHistory.push({date,value,invested});state.portfolioHistory=state.portfolioHistory.slice(-730)}
function totals(){let income=state.transactions.filter(x=>x.type==='income').reduce((a,x)=>a+(+x.amount||0),0),expense=state.transactions.filter(x=>x.type!=='income').reduce((a,x)=>a+(+x.amount||0),0),invested=state.investments.reduce((a,x)=>a+(+x.quantity||0)*(+x.averagePrice||0),0),current=state.investments.reduce((a,x)=>a+(+x.quantity||0)*(+x.currentPrice||+x.averagePrice||0),0);return{income,expense,invested,current,balance:income-expense,wealth:income-expense+current}}

