async function searchMarket(q){let box=document.getElementById('marketResults');box.innerHTML='<div class="loader">Buscando no mercado<span></span></div>';let rows=[],token=CFG.market?.brapiToken||'',twelve=CFG.market?.twelveDataKey||'demo';try{if(marketTab==='br'&&q){let r=await fetch(`https://brapi.dev/api/quote/list?search=${encodeURIComponent(q)}&limit=12`,{headers:token?{Authorization:`Bearer ${token}`}:{}}),j=await r.json();rows=(j.stocks||[]).map(z=>({id:z.stock,ticker:z.stock,name:z.name||z.stock,category:z.subType==='fii'?'FIIs':z.subType==='etf'?'ETFs':'Ações',price:+z.close||0,change:+z.change||0,source:'BRAPI',provider:'brapi'}))}if((marketTab==='us'||marketTab==='crypto')&&q){let r=await fetch(`https://api.twelvedata.com/symbol_search?symbol=${encodeURIComponent(q)}&outputsize=12&apikey=${encodeURIComponent(twelve)}`),j=await r.json();rows=(j.data||[]).filter(z=>marketTab==='crypto'?/crypto/i.test(z.instrument_type||''):(!z.country||/united states/i.test(z.country))).map(z=>({id:z.symbol,ticker:z.symbol,name:z.instrument_name||z.symbol,category:marketTab==='crypto'?'Criptomoedas':'Stocks',price:0,change:0,source:'Twelve Data',provider:'twelve'}))}}catch(e){console.warn(e)}if(!rows.length)rows=catalog[marketTab].filter(x=>!q||x.join(' ').toLowerCase().includes(q.toLowerCase())).map(x=>({id:x[0],ticker:x[0],name:x[1],category:x[2],price:0,change:0,source:marketTab==='br'?'BRAPI':'Twelve Data',provider:marketTab==='br'?'brapi':'twelve'}));marketResults=new Map(rows.map(x=>[x.id,x]));box.innerHTML=rows.map(x=>`<div class="market-row"><button class="asset-symbol" data-view="${safe(x.id)}">${safe(x.ticker.slice(0,7))}</button><b>${safe(x.name)}<small>${safe(x.category)} • ${x.source}</small></b><span>${x.price?money(x.price):'Ver cotação'}<em class="${x.change>=0?'up':'down'}">${x.change?x.change.toFixed(2)+'%':''}</em></span><button class="add-market" data-add="${safe(x.id)}">＋ Carteira</button></div>`).join('')||empty('⌕','Nenhum ativo encontrado','Tente buscar por outro nome ou ticker.')}
async function hydrateMarketQuotes(rows){
 let token=CFG.market?.brapiToken||'',key=CFG.market?.twelveDataKey||'demo';
 rows.forEach(x=>{let saved=state.investments.find(i=>(i.ticker||'').toUpperCase()===(x.ticker||'').toUpperCase());if(saved&&!x.price)x.price=+saved.currentPrice||+saved.averagePrice||0});
 let brazil=rows.filter(x=>x.provider==='brapi'&&x.ticker).slice(0,18);
 if(brazil.length)try{let symbols=brazil.map(x=>encodeURIComponent(x.ticker)).join(','),response=await fetch(`https://brapi.dev/api/quote/${symbols}?fundamental=false`,{headers:token?{Authorization:`Bearer ${token}`}:{}}),json=await response.json();(json.results||[]).forEach(quote=>{let row=brazil.find(x=>x.ticker===quote.symbol);if(row){row.price=+quote.regularMarketPrice||row.price||0;row.change=+quote.regularMarketChangePercent||0}})}catch(error){console.warn('Cotação BRAPI indisponível',error)}
 let globals=rows.filter(x=>x.provider==='twelve'&&x.ticker).slice(0,10);
 await Promise.all(globals.map(async row=>{try{let quote=await fetch(`https://api.twelvedata.com/quote?symbol=${encodeURIComponent(row.ticker)}&apikey=${encodeURIComponent(key)}`).then(r=>r.json());row.price=+(quote.close||quote.price)||row.price||0;row.change=+(quote.percent_change||quote.change_percent)||row.change||0}catch(error){console.warn('Cotação global indisponível',error)}}));
 return rows
}
searchMarket=async function(q){
 let box=document.getElementById('marketResults');box.innerHTML='<div class="loader">Buscando cotações de hoje<span></span></div>';
 let rows=[],token=CFG.market?.brapiToken||'',twelve=CFG.market?.twelveDataKey||'demo',brTabs=['br','fii','bdr'],globalTabs=['us','reit','crypto'];
 try{
  if(brTabs.includes(marketTab)&&q){let r=await fetch(`https://brapi.dev/api/quote/list?search=${encodeURIComponent(q)}&limit=18`,{headers:token?{Authorization:`Bearer ${token}`}:{}}),j=await r.json();rows=(j.stocks||[]).map(z=>{let sub=(z.subType||'').toLowerCase(),category=sub==='fii'?'FIIs':sub==='bdr'?'BDRs':sub==='etf'?'ETFs':'Ações';return{id:z.stock,ticker:z.stock,name:z.name||z.stock,category,price:+z.close||0,change:+z.change||0,source:'Mercado brasileiro',provider:'brapi'}}).filter(x=>marketTab==='fii'?x.category==='FIIs':marketTab==='bdr'?x.category==='BDRs':x.category==='Ações'||x.category==='ETFs')}
  if(globalTabs.includes(marketTab)&&q){let r=await fetch(`https://api.twelvedata.com/symbol_search?symbol=${encodeURIComponent(q)}&outputsize=18&apikey=${encodeURIComponent(twelve)}`),j=await r.json();rows=(j.data||[]).filter(z=>marketTab==='crypto'?/crypto/i.test(z.instrument_type||''):marketTab==='reit'?/reit/i.test(`${z.instrument_type||''} ${z.instrument_name||''}`):(!z.country||/united states/i.test(z.country))).map(z=>({id:z.symbol,ticker:z.symbol,name:z.instrument_name||z.symbol,category:marketTab==='crypto'?'Criptomoedas':marketTab==='reit'?'REITs':'Stocks',price:0,change:0,source:'Mercado internacional',provider:'twelve'}))}
 }catch(e){console.warn(e)}
 if(!rows.length)rows=(catalog[marketTab]||catalog.br).filter(x=>!q||x.join(' ').toLowerCase().includes(q.toLowerCase())).map(x=>({id:x[0],ticker:x[0],name:x[1],category:x[2],price:0,change:0,source:'Catálogo de ativos',provider:brTabs.includes(marketTab)?'brapi':marketTab==='fixed'?'fixed':'twelve'}));
 rows=await hydrateMarketQuotes(rows);marketResults=new Map(rows.map(x=>[x.id,x]));
 box.innerHTML=rows.map(x=>`<div class="market-row"><button class="asset-symbol" data-view="${safe(x.id)}">${safe(x.ticker.slice(0,9))}</button><b>${safe(x.name)}<small>${safe(x.category)}</small></b><span class="market-quote"><small>Cotação hoje</small><b>${x.price?money(x.price):marketTab==='fixed'?'Cadastro manual':'Indisponível'}</b><em class="${x.change>=0?'up':'down'}">${x.change?`${x.change>=0?'+':''}${x.change.toFixed(2).replace('.',',')}%`:'Sem variação'}</em></span><button class="add-market" data-add="${safe(x.id)}">＋ Carteira</button></div>`).join('')||empty('⌕','Nenhum ativo encontrado','Tente buscar por outro nome ou categoria.')
};
async function viewMarket(x){document.getElementById('marketChartTitle').textContent=`${x.ticker} • ${x.name}`;document.getElementById('marketChartHint').textContent='Carregando evolução...';let values=[],source=x.source||'Carteira',token=CFG.market?.brapiToken||'',key=CFG.market?.twelveDataKey||'demo';try{if(x.provider==='brapi'){let r=await fetch(`https://brapi.dev/api/v2/stocks/historical?symbols=${encodeURIComponent(x.ticker)}&range=1mo&interval=1d&sortOrder=asc`,{headers:token?{Authorization:`Bearer ${token}`}:{}}),j=await r.json(),data=j.results?.[0]?.data||j.results?.[0]?.historicalDataPrice||[];values=data.map(v=>+(v.close||v.adjustedClose)).filter(Number.isFinite)}else if(x.provider!=='fixed'){let [series,quote]=await Promise.all([fetch(`https://api.twelvedata.com/time_series?symbol=${encodeURIComponent(x.ticker)}&interval=1day&outputsize=30&apikey=${encodeURIComponent(key)}`).then(r=>r.json()),fetch(`https://api.twelvedata.com/quote?symbol=${encodeURIComponent(x.ticker)}&apikey=${encodeURIComponent(key)}`).then(r=>r.json())]);values=(series.values||[]).reverse().map(v=>+v.close).filter(Number.isFinite);x.price=+(quote.close||quote.price||x.price)||0}}catch(e){console.warn(e)}if(!values.length)values=Array.from({length:24},(_,i)=>50+Math.sin(i*.7)*8+i);document.getElementById('detailPrice').textContent=x.price?money(x.price):x.provider==='fixed'?'Rentabilidade cadastrada manualmente':'Histórico do ativo';let min=Math.min(...values),max=Math.max(...values),p=values.map((z,i)=>`${i?'L':'M'}${i/(values.length-1)*600} ${210-(z-min)/(max-min||1)*170}`).join(' ');document.querySelector('.detail-chart path').setAttribute('d',p);document.getElementById('marketChartHint').textContent=`${source}. Dados informativos, não constituem recomendação.`}

function bindSettings(){let p=document.getElementById('profileForm');if(!p)return;p.onsubmit=e=>{e.preventDefault();state.profile.name=new FormData(e.target).get('name').trim();save();toast('Perfil atualizado','Sua identidade foi salva.')};let counts=[['Tarefas',state.tasks.length],['Hábitos',state.habits.length],['Finanças',state.transactions.length],['Investimentos',state.investments.length],['Metas',state.goals.length],['Notas',state.notes.length]];document.getElementById('storageStats').innerHTML=counts.map(x=>`<span><b>${x[1]}</b><small>${x[0]}</small></span>`).join('');let last=localStorage.getItem('luar-last-backup');if(last)document.getElementById('backupInfo').textContent=`Último backup: ${new Date(last).toLocaleString('pt-BR')}`;document.getElementById('exportBackup').onclick=exportBackup;document.getElementById('importBackup').onclick=()=>document.getElementById('backupFile').click();document.getElementById('backupFile').onchange=importBackup;document.getElementById('resetBtn').onclick=()=>{if(confirm('Apagar definitivamente todos os dados locais da LUAR?')){state=structuredClone(EMPTY);localStorage.removeItem('luar-state');buildPages();render();toast('LUAR reiniciado','Sua nova jornada começa agora.')}}}
function exportBackup(){let stamp=new Date(),payload={app:'LUAR',version:2,exportedAt:stamp.toISOString(),data:state},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`LUAR-backup-${stamp.toISOString().slice(0,10)}.json`;document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);localStorage.setItem('luar-last-backup',stamp.toISOString());document.getElementById('backupInfo').textContent=`Último backup: ${stamp.toLocaleString('pt-BR')}`;toast('Backup exportado','Guarde o arquivo em um local seguro.')}
function importBackup(e){let file=e.target.files?.[0];if(!file)return;let reader=new FileReader();reader.onload=()=>{try{let payload=JSON.parse(reader.result),data=payload.data||payload;if(!data.profile||!Array.isArray(data.tasks)||!Array.isArray(data.transactions))throw Error('estrutura inválida');if(confirm('Importar este backup e substituir os dados atuais?')){state={...structuredClone(EMPTY),...data};save();buildPages();render();showPage('settings');toast('Backup restaurado','Todas as informações foram importadas.')}}catch(err){toast('Backup inválido','Selecione um arquivo de backup criado pela LUAR.')}finally{e.target.value=''}};reader.readAsText(file)}

const pages=[...document.querySelectorAll('.page')],sidebar=document.getElementById('sidebar');function showPage(x){pages.forEach(p=>p.classList.toggle('active',p.id===x));document.querySelectorAll('.nav').forEach(n=>n.classList.toggle('active',n.dataset.page===x));sidebar.classList.remove('open');history.replaceState(null,'','#'+x);scrollTo({top:0,behavior:'auto'});if(x==='investments'&&!marketResults.size)searchMarket('')}
async function previousMarketClose(x){if(x.provider==='fixed')return +x.price||0;let token=CFG.market?.brapiToken||'',key=CFG.market?.twelveDataKey||'demo';try{if(x.provider==='brapi'){let r=await fetch(`https://brapi.dev/api/v2/stocks/historical?symbols=${encodeURIComponent(x.ticker)}&range=5d&interval=1d&sortOrder=asc`,{headers:token?{Authorization:`Bearer ${token}`}:{}}),j=await r.json(),data=j.results?.[0]?.data||j.results?.[0]?.historicalDataPrice||[],closes=data.map(v=>({date:String(v.date||v.datetime||''),close:+(v.close||v.adjustedClose)})).filter(v=>Number.isFinite(v.close));return closes.filter(v=>!v.date||v.date.slice(0,10)<today()).at(-1)?.close||closes.at(-2)?.close||closes.at(-1)?.close||+x.price||0}let r=await fetch(`https://api.twelvedata.com/time_series?symbol=${encodeURIComponent(x.ticker)}&interval=1day&outputsize=7&apikey=${encodeURIComponent(key)}`),j=await r.json(),values=(j.values||[]).map(v=>({date:String(v.datetime||''),close:+v.close})).filter(v=>Number.isFinite(v.close));return values.find(v=>v.date.slice(0,10)<today())?.close||values[1]?.close||values[0]?.close||+x.price||0}catch{return +x.price||0}}
async function prepareInvestmentForm(x){toast('Buscando preço anterior','Consultando o último fechamento disponível.');let previous=await previousMarketClose(x),current=+x.price||previous||0;openForm('investments',null,{name:x.name,ticker:x.ticker,category:x.category,quantity:1,currentPrice:current,averagePrice:previous||current});let form=document.getElementById('entityForm'),price=form.elements.averagePrice;if(price){let note=document.createElement('small');note.className='field-hint';note.textContent=previous?'Preço médio preenchido com o fechamento do último dia disponível.':'Informe o preço médio manualmente para este ativo.';price.closest('label').appendChild(note)}}
document.addEventListener('click',e=>{let p=e.target.closest('[data-page]');if(p){e.preventDefault();showPage(p.dataset.page)}let c=e.target.closest('[data-create]');if(c)openForm(c.dataset.create);let m=e.target.closest('[data-modal]');if(m)openForm(m.dataset.modal==='tarefa'?'tasks':m.dataset.modal==='meta'?'goals':'transactions');let a=e.target.closest('[data-action]');if(a)act(a.dataset.action,a.dataset.entity,a.dataset.id);let mood=e.target.closest('[data-mood]');if(mood)selectMood(mood.dataset.mood,mood);let add=e.target.closest('[data-add]');if(add){let x=marketResults.get(add.dataset.add);if(x)prepareInvestmentForm(x)}let v=e.target.closest('[data-view]');if(v)viewMarket(marketResults.get(v.dataset.view));let h=e.target.closest('[data-holding]');if(h){let x=state.investments.find(z=>z.id===h.dataset.holding);viewMarket({ticker:x.ticker,name:x.name,price:x.currentPrice,source:'Sua carteira',provider:x.category==='Ações'||x.category==='FIIs'||x.category==='BDRs'?'brapi':x.category==='Renda Fixa'||x.category==='Tesouro Direto'?'fixed':'twelve'})}let period=e.target.closest('[data-portfolio-period]');if(period){portfolioPeriod=period.dataset.portfolioPeriod;document.querySelectorAll('[data-portfolio-period]').forEach(b=>b.classList.toggle('active',b===period));renderPortfolioBigChart()}let tab=e.target.closest('[data-market]');if(tab){marketTab=tab.dataset.market;document.querySelectorAll('[data-market]').forEach(b=>b.classList.toggle('active',b===tab));searchMarket('')}});
let draggedTaskId=null;
document.addEventListener('dragstart',e=>{let task=e.target.closest('.task[draggable="true"]');if(!task)return;draggedTaskId=task.dataset.taskId;task.classList.add('dragging');e.dataTransfer.effectAllowed='move';e.dataTransfer.setData('text/plain',draggedTaskId)});
document.addEventListener('dragover',e=>{let column=e.target.closest('[data-task-column]');if(!column)return;e.preventDefault();e.dataTransfer.dropEffect='move';document.querySelectorAll('[data-task-column]').forEach(x=>x.classList.toggle('drag-over',x===column))});
document.addEventListener('dragleave',e=>{let column=e.target.closest('[data-task-column]');if(column&&!column.contains(e.relatedTarget))column.classList.remove('drag-over')});
