document.addEventListener('dragend',()=>{document.querySelectorAll('.task.dragging,[data-task-column].drag-over').forEach(x=>x.classList.remove('dragging','drag-over'));draggedTaskId=null});
document.addEventListener('click',e=>{let nav=e.target.closest('[data-agenda-nav]');if(nav){agendaMonth.setMonth(agendaMonth.getMonth()+(+nav.dataset.agendaNav||0));selectedAgendaDate=dateKey(new Date(agendaMonth.getFullYear(),agendaMonth.getMonth(),1));renderBigAgenda();return}let day=e.target.closest('[data-agenda-date]');if(day){selectedAgendaDate=day.dataset.agendaDate;renderBigAgenda();return}if(e.target.closest('[data-add-agenda]'))openForm('events',null,{date:selectedAgendaDate})});
