document.addEventListener('click',e=>{let tab=e.target.closest('[data-invest-section]');if(!tab)return;document.querySelectorAll('[data-invest-section]').forEach(x=>x.classList.toggle('active',x===tab));let targets={summary:'investmentSummary',holdings:'investmentHoldings',evolution:'investmentEvolution',allocation:'investmentAllocation',market:'investmentMarket'},target=document.getElementById(targets[tab.dataset.investSection]);target?.scrollIntoView({behavior:'smooth',block:'start'})});
